/** icon('trash', 'mr-1') => elemen <svg> sebesar 1em, mengikuti warna teks. */
function icon(string $name, string $class = ''): string {
    $paths = $GLOBALS['STELLA_ICONS'][$name] ?? '';
    return '<svg class="icon' . ($class !== '' ? ' ' . $class : '') . '" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">' . $paths . '</svg>';
}
